import{Z as t,e as o,f as a,a0 as n}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Telegram","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/messaging/telegram.md","filePath":"integrations/messaging/telegram.md","lastUpdated":1780377007000}'),i={name:"integrations/messaging/telegram.md"};function r(s,e,l,h,c,g){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h1><p>Connect Telegram to send a message when a visitor completes your form. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Messaging</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Telegram</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-create-a-telegram-bot" tabindex="-1">Step 2. Create a Telegram Bot <a class="header-anchor" href="#step-2-create-a-telegram-bot" aria-label="Permalink to &quot;Step 2. Create a Telegram Bot&quot;">​</a></h3><ol><li>Open Telegram and search for <strong>@BotFather</strong>.</li><li>Start a chat and send the command <code>/newbot</code>.</li><li>Follow the prompts to give your bot a name and username.</li><li>Copy the <strong>Bot Token</strong> provided after creation.</li><li>Paste this value into the <strong>Bot Token</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar to verify the connection.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Set the recipient or channel supported by the integration. Use the variable picker to include the submitted values your team needs in the message.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h3 id="step-5-get-your-chat-id" tabindex="-1">Step 5. Get Your Chat ID <a class="header-anchor" href="#step-5-get-your-chat-id" aria-label="Permalink to &quot;Step 5. Get Your Chat ID&quot;">​</a></h3><ol><li>Start a conversation with your bot, or add it to a group or channel.</li><li>Send a message in the chat where you&#39;d like the bot to post (this triggers a &quot;message update&quot;).</li><li>Visit the following URL in your browser (replace the token): <code>https://api.telegram.org/bot&lt;YOUR_BOT_TOKEN&gt;/getUpdates</code></li><li>Look for a <code>chat</code> object in the response. It will look something like: <code>&quot;chat&quot;: { &quot;id&quot;: -1001234567890, &quot;type&quot;: &quot;channel&quot;, &quot;title&quot;: &quot;Announcements&quot; }</code></li><li>Copy the <code>id</code> value and paste it into the <strong>Chat ID</strong> field when setting up the form integration.</li></ol><blockquote><p>💡 You can use a chat ID from a user, group, or channel — Telegram will route the message based on the ID automatically.</p></blockquote><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Check the intended recipient or channel for the test message and verify that its values match the submission.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',16)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
